-- Reviewed P99 exchanges using existing quest primitives. Quest faction gating remains intentionally bypassed.
-- Extended by the 62-script Velious backlog: reviewed supply, delivery and Tunarean Regiment reward branches. The initial Krofer squad encounter remains deferred.
local item_lib = require("items")

function event_trade(e)
  if item_lib.check_turn_in(e.trade, { item1 = 25281 }) then
    e.self:Say("It's hard to belive a " .. e.other:GetRaceName() .. " like you is going to make a trip like this. I don't envy you little fool.")
    e.other:SummonItem(25107)
  elseif item_lib.check_turn_in(e.trade, { item1 = 25279 }) then
    e.self:Say("Here you go " .. e.other:GetCleanName() .. ". I dunno why master Wenglawks trusts you with this but take it anyways and don't mess up.")
    e.self:Emote("smacks his fists together as he looks at you.")
    e.other:SummonItem(25104)
  elseif item_lib.check_turn_in(e.trade, { item1 = 25280 }) then
    e.self:Say("Another delivery eh? Be careful with this spear, if you break it I'll break you.")
    e.other:SummonItem(25106)
  elseif item_lib.check_turn_in(e.trade, { item1 = 1722 }) then
    e.self:Say("So you are the mercenary I have been hearing about! Not what I expected. Anyways, here is your reward. Carry it well. Also, this noble's seal will prove your loyalty to anyone who is skeptical.")
    e.other:SummonItem(1721)
    e.other:SummonItem(1723)
    e.other:AddEXP(2000)
  end
  -- Return unrelated and surplus offers on both accepted and rejected trades.
  item_lib.return_items(e.self, e.other, e.trade)
end
